import { describe, it, expect, beforeAll } from 'vitest';
import { createElement as h, act } from 'react';
import { createRoot } from 'react-dom/client';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
const W = 1200;
beforeAll(() => {
  (globalThis as any).ResizeObserver = class { constructor(private cb: any) {} observe() { this.cb([]); } disconnect() {} unobserve() {} };
  Object.defineProperty(HTMLElement.prototype, 'clientWidth', { get() { return this.classList?.contains('dash-grid') ? W : 320; } });
  Object.defineProperty(HTMLElement.prototype, 'clientHeight', { get() { return 220; } });
  const orig = HTMLElement.prototype.getBoundingClientRect;
  HTMLElement.prototype.getBoundingClientRect = function () {
    if (this.classList.contains('dash-grid')) return { left: 0, top: 100, right: W, bottom: 2000, width: W, height: 1900, x: 0, y: 100, toJSON() {} } as DOMRect;
    return orig.call(this);
  };
  window.scrollBy = () => {};
});

const ptr = (target: EventTarget, type: string, x: number, y: number) =>
  target.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, button: 0, clientX: x, clientY: y }));
const saved = () => JSON.parse(localStorage.getItem('viz-dashboard:v1')!).layout as any[];
const get = (id: string) => saved().find((i) => i.i === id);
const overlaps = (l: any[]) => l.some((a) => l.some((b) => a !== b && a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y));
const header = (title: string) => [...document.querySelectorAll('section.widget')].find((s) => s.querySelector('h2')!.textContent === title)!;

describe('dashboard', () => {
  const errors: unknown[] = [];
  it('renders, drags, resizes, keyboard, persists', async () => {
    const origErr = console.error; console.error = (...a) => { errors.push(a); origErr(...a); };
    localStorage.clear();
    const { App } = await import('/home/sandbox/workspace/src/App.tsx');
    const { ThemeProvider } = await import('@gravity-ui/uikit');
    const el = document.createElement('div'); document.body.append(el);
    const root = createRoot(el);
    await act(async () => root.render(h(ThemeProvider as any, { theme: 'light' }, h(App))));

    expect(document.querySelectorAll('section.widget').length).toBe(9);
    expect(document.querySelectorAll('polyline').length).toBeGreaterThan(4); // spark + line chart
    expect(document.querySelectorAll('.viz-segmented__part').length).toBe(5);
    console.log('svg count', document.querySelectorAll('svg').length);

    // drag "Выручка" (x0,y0) to column 6
    const hdr = header('Выручка').querySelector('header')!;
    await act(async () => { ptr(hdr, 'pointerdown', 50, 118); });
    expect(document.querySelector('.dash-grid__placeholder')).not.toBeNull();
    await act(async () => { ptr(window, 'pointermove', 50 + 3 * 101, 118); ptr(window, 'pointermove', 50 + 6 * 101, 118); });
    await act(async () => { ptr(window, 'pointerup', 50 + 6 * 101, 118); });
    expect(get('revenue')).toMatchObject({ x: 6, y: 0 });
    expect(overlaps(saved())).toBe(false);
    console.log('after drag', saved().map((i) => `${i.i}:${i.x},${i.y},${i.w}x${i.h}`).join(' '));

    // resize traffic via corner: -2 cols, +1 row
    const t = get('traffic');
    const corner = header('Посещаемость по дням').parentElement!.querySelector('.dash-grid__resize')!;
    const sx = (t.x + t.w) * 101 - 20, sy = 100 + (t.y + t.h) * 84 - 20;
    await act(async () => { ptr(corner, 'pointerdown', sx, sy); });
    await act(async () => { ptr(window, 'pointermove', sx - 202, sy + 84); });
    await act(async () => { ptr(window, 'pointerup', sx - 202, sy + 84); });
    expect(get('traffic')).toMatchObject({ w: t.w - 2, h: t.h + 1 });
    expect(overlaps(saved())).toBe(false);

    // Escape cancels
    const before = JSON.stringify(saved());
    const ph = header('План выручки на период').querySelector('header')!;
    await act(async () => { ptr(ph, 'pointerdown', 50, 1000); });
    await act(async () => { ptr(window, 'pointermove', 600, 200); });
    await act(async () => { window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' })); });
    await act(async () => { ptr(window, 'pointerup', 600, 200); });
    expect(JSON.stringify(saved())).toBe(before);

    // keyboard: move orders right, then grow height
    const o = get('orders');
    const grip = header('Заказы').querySelector('.widget__grip') as HTMLElement;
    await act(async () => { grip.focus(); grip.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true })); });
    expect(get('orders').x).toBe(o.x + 1);
    await act(async () => { grip.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', shiftKey: true, bubbles: true })); });
    expect(get('orders').h).toBe(o.h + 1);
    expect(document.querySelector('.dash-grid__live')!.textContent).toContain('Заказы');
    expect(overlaps(saved())).toBe(false);

    // remove + re-add
    const removeBtn = header('Источники трафика').querySelector('button[aria-label^="Убрать"]') as HTMLElement;
    await act(async () => { removeBtn.click(); });
    expect(get('sources')).toBeUndefined();
    expect(document.querySelectorAll('section.widget').length).toBe(8);

    // table toggle
    const tblBtn = header('Выручка по категориям').querySelector('button[aria-label="Показать таблицей"]') as HTMLElement;
    await act(async () => { tblBtn.click(); });
    expect(header('Выручка по категориям').querySelectorAll('tbody tr').length).toBe(6);

    // compact toggle
    const sw = [...document.querySelectorAll('label')].find((l) => l.textContent?.includes('Прижимать'))!.querySelector('input')!;
    await act(async () => { sw.click(); });
    expect(JSON.parse(localStorage.getItem('viz-dashboard:v1')!).compact).toBe(true);
    expect(overlaps(saved())).toBe(false);

    // edit off: no grips
    const ed = [...document.querySelectorAll('label')].find((l) => l.textContent?.includes('Редактирование'))!.querySelector('input')!;
    await act(async () => { ed.click(); });
    expect(document.querySelectorAll('.widget__grip').length).toBe(0);
    expect(document.querySelectorAll('.dash-grid__resize').length).toBe(0);

    await act(async () => root.unmount());
    // re-mount: persisted
    const root2 = createRoot(el);
    await act(async () => root2.render(h(ThemeProvider as any, { theme: 'light' }, h(App))));
    expect(document.querySelectorAll('section.widget').length).toBe(8);
    console.error = origErr;
    expect(errors).toEqual([]);
  });
});
EOF
